mapper.select:
SELECT d.distributor_self
FROM distribution_distributor d
WHERE d.company_id = #{companyId}
	AND d.distributor_id = #{distributorId}
LIMIT 1

choose.when:
SELECT COUNT(*) FROM items i
WHERE i.company_id = #{companyId}
	AND EXISTS (
		SELECT 1 FROM distribution_distributor d
		WHERE d.distributor_id = #{distributorId}
			AND d.company_id = #{companyId}
	)
	AND i.item_category IN

		#{k}

choose.otherwise:
SELECT COUNT(*) FROM items i
INNER JOIN distribution_distributor d
	ON d.distributor_id = #{distributorId} AND d.company_id = #{companyId}
INNER JOIN distribution_distributor_items ddi
	ON ddi.item_id = i.item_id
	AND ddi.company_id = i.company_id
	AND ddi.distributor_id = #{distributorId}
WHERE i.company_id = #{companyId}
	AND i.item_category IN

		#{k}

choose.when:
